tape( 'the function performs a reduction on an ndarray (no dimensions, row-major)', function test( t ) {
	var actual;
	var mask;
	var arr;
	var x;

	x = new ndarray( 'float64', new Float64Array( [ -1.0, 2.0, -3.0, 4.0 ] ), [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	mask = new ndarray( 'uint8', new Uint8Array( [ 0, 0, 0, 1 ] ), [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );

	actual = mskmax( x, mask, {
		'dims': [],
		'keepdims': false
	});

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.strictEqual( String( getDType( actual ) ), 'float64', 'returns expected value' );
	t.deepEqual( getShape( actual ), [ 2, 2 ], 'returns expected value' );
	t.strictEqual( getOrder( actual ), getOrder( x ), 'returns expected value' );

	arr = ndarray2array( actual );
	t.strictEqual( arr[ 0 ][ 0 ], -1.0, 'returns expected value' );
	t.strictEqual( arr[ 0 ][ 1 ], 2.0, 'returns expected value' );
	t.strictEqual( arr[ 1 ][ 0 ], -3.0, 'returns expected value' );
	t.strictEqual( isnan( arr[ 1 ][ 1 ] ), true, 'returns expected value' );

	actual = mskmax( x, mask, {
		'dims': [],
		'keepdims': true
	});

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.strictEqual( String( getDType( actual ) ), 'float64', 'returns expected value' );
	t.deepEqual( getShape( actual ), [ 2, 2 ], 'returns expected value' );
	t.strictEqual( getOrder( actual ), getOrder( x ), 'returns expected value' );

	arr = ndarray2array( actual );
	t.strictEqual( arr[ 0 ][ 0 ], -1.0, 'returns expected value' );
	t.strictEqual( arr[ 0 ][ 1 ], 2.0, 'returns expected value' );
	t.strictEqual( arr[ 1 ][ 0 ], -3.0, 'returns expected value' );
	t.strictEqual( isnan( arr[ 1 ][ 1 ] ), true, 'returns expected value' );

	t.end();
});

