tape( 'the function returns an output ndarray having the same data type as the input ndarray, by default', function test( t ) {
	var actual;
	var mask;
	var x;

	mask = new ndarray( 'uint8', new Uint8Array( [ 0, 0, 0, 1 ] ), [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );

	x = new ndarray( 'float64', new Float64Array( [ -1.0, 2.0, -3.0, 4.0 ] ), [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	actual = mskmax( x, mask );
	t.strictEqual( String( getDType( actual ) ), 'float64', 'returns expected value' );
	t.strictEqual( actual.get(), 2.0, 'returns expected value' );

	x = new ndarray( 'float32', new Float32Array( [ -1.0, 2.0, -3.0, 4.0 ] ), [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	actual = mskmax( x, mask );
	t.strictEqual( String( getDType( actual ) ), 'float32', 'returns expected value' );
	t.strictEqual( actual.get(), 2.0, 'returns expected value' );

	x = new ndarray( 'int8', new Int8Array( [ -1, 2, -3, 4 ] ), [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	actual = mskmax( x, mask );
	t.strictEqual( String( getDType( actual ) ), 'int8', 'returns expected value' );
	t.strictEqual( actual.get(), 2, 'returns expected value' );

	x = new ndarray( 'generic', [ -1.0, 2.0, -3.0, 4.0 ], [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	actual = mskmax( x, mask );
	t.strictEqual( String( getDType( actual ) ), 'generic', 'returns expected value' );
	t.strictEqual( actual.get(), 2.0, 'returns expected value' );

	t.end();
});

