tape( 'the function supports broadcasting a mask ndarray to the shape of the input ndarray', function test( t ) {
	var expected;
	var actual;
	var mask;
	var x;

	x = new ndarray( 'float64', new Float64Array( [ -1.0, 2.0, -3.0, 4.0 ] ), [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );

	// Mask the second column:
	mask = new ndarray( 'uint8', new Uint8Array( [ 0, 1 ] ), [ 2 ], [ 1 ], 0, 'row-major' );

	actual = mskmax( x, mask );
	t.strictEqual( actual.get(), -1.0, 'returns expected value' );

	actual = mskmax( x, mask, {
		'dims': [ 1 ]
	});
	expected = [ -1.0, -3.0 ];
	t.deepEqual( ndarray2array( actual ), expected, 'returns expected value' );

	actual = mskmax( x, mask, {
		'dims': [ 0 ]
	});
	t.strictEqual( actual.get( 0 ), -1.0, 'returns expected value' );
	t.strictEqual( isnan( actual.get( 1 ) ), true, 'returns expected value' );

	// Mask the first row:
	mask = new ndarray( 'uint8', new Uint8Array( [ 1, 0 ] ), [ 2, 1 ], [ 1, 1 ], 0, 'row-major' );

	actual = mskmax( x, mask, {
		'dims': [ 0 ]
	});
	expected = [ -3.0, 4.0 ];
	t.deepEqual( ndarray2array( actual ), expected, 'returns expected value' );

	// Zero-dimensional mask:
	mask = new ndarray( 'uint8', new Uint8Array( [ 0 ] ), [], [ 0 ], 0, 'row-major' );

	actual = mskmax( x, mask );
	t.strictEqual( actual.get(), 4.0, 'returns expected value' );

	t.end();
});

